// POST /api/oauth/token - OAuth token exchange proxy
//
// Proxies authorization_code and refresh_token grant requests to OAuth providers,
// injecting the client_secret server-side so it never ships in client code.
//
// Supports multiple client IDs per provider (e.g., Google friction-free + verified-full),
// each with its own Cloudflare Worker secret.
//
// AUTH MODEL (C2):
// - authorization_code grants are pre-login (PKCE binds the code), so no
//   bearer is required.
// - refresh_token grants REQUIRE Authorization: Bearer pf_… and the bearer
//   must not be revoked. Without this, anyone with a leaked refresh_token
//   could launder it through our client_secret to mint access tokens.

import type { Env } from '../../index'
import { errorResponse } from '../types'
import { verifyPfToken } from '../pf-token'
import { isTokenRevoked } from './auth-logout'
import { safeAudit } from '../db/queries'
import { generateUUID } from '../uuid'

/** Supported grant types */
type GrantType = 'authorization_code' | 'refresh_token';

/** A single client registration within a provider */
interface ClientRegistration {
  clientId: string;
  /** Key in Cloudflare env where this client's secret is stored */
  secretEnvKey: string;
}

/** Provider config — token URL and registered client IDs */
interface ProviderConfig {
  tokenUrl: string;
  clients: ClientRegistration[];
}

